#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<long long>a(n),b(m);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
for(int i=0;i<m;++i)scanf("%lld",&b[i]);
vector<long long>r;r.reserve(n+m);
int i=0,j=0;
while(i<n&&j<m){if(a[i]<=b[j])r.push_back(a[i++]);else r.push_back(b[j++]);}
while(i<n)r.push_back(a[i++]);
while(j<m)r.push_back(b[j++]);
for(size_t k=0;k<r.size();++k){if(k)printf(" ");printf("%lld",r[k]);}
printf("\n");return 0;}

